/**
 * The Worker's environment and how to reach the Durable Objects.
 *
 * `Env` is generated by `bun run types` from wrangler.example.jsonc and .dev.vars.example
 * into worker-configuration.d.ts. GITHUB_CLIENT_SECRET and VAULT_KEY are secrets.
 *
 * A deployment may leave some bindings out, so code reads them through `optionalEnv`:
 *
 * - the inbox's Rate Limiting bindings (a configuration that predates them skips the checks);
 * - `UNIVERSE`: left out means the host's own public host; "" switches the universe off;
 * - `UNIVERSE_SERVICE`: the universe Worker as a service binding, when it shares the zone.
 */

export type HostEnv = Env;

export interface OptionalEnv {
  INBOX_IP_LIMIT?: RateLimit;
  INBOX_SENDER_LIMIT?: RateLimit;
  UNIVERSE?: string;
  UNIVERSE_SERVICE?: Fetcher;
}

/** The bindings a deployment may leave out, typed as such. */
export function optionalEnv(env: HostEnv): OptionalEnv {
  return env as unknown as OptionalEnv;
}

/** The one Accounts instance every request talks to. */
export const ACCOUNTS_NAME = "accounts";

export function accountsOf(env: HostEnv) {
  return env.ACCOUNTS.getByName(ACCOUNTS_NAME);
}

/** The Tau of a handle: one Durable Object per handle, `idFromName(handle)`. */
export function tauOf(env: HostEnv, handle: string) {
  return env.TAU.getByName(handle);
}

const LOCAL_HOSTS = new Set(["localhost", "127.0.0.1", "[::1]"]);

/** A request to this machine (`wrangler dev`, tests): the only place DEV_LOGIN works. */
export function isLocal(url: URL): boolean {
  return LOCAL_HOSTS.has(url.hostname);
}

export function devLoginEnabled(env: HostEnv, url: URL): boolean {
  return env.DEV_LOGIN === "1" && isLocal(url);
}

export function fakeProviderEnabled(env: HostEnv): boolean {
  return env.FAKE_PROVIDER === "1";
}

/**
 * The host's own origin: `https://<PUBLIC_HOST>` when it is set, else the request URL's
 * origin. State-changing requests must carry it as `Origin`.
 */
export function hostOrigin(env: HostEnv, url: URL): string {
  const configured = (env.PUBLIC_HOST ?? "").trim().toLowerCase();
  return configured ? `https://${configured}` : url.origin;
}

/** Who may create an account: anyone, a list of lower-cased logins, or nobody. */
export type Signup = { open: true } | { open: false; logins: ReadonlySet<string> };

export function signupPolicy(env: HostEnv): Signup {
  const raw = (env.SIGNUP ?? "").trim().toLowerCase();
  if (raw === "open") return { open: true };
  const logins = raw
    .split(",")
    .map((login) => login.trim())
    .filter((login) => login !== "");
  return { open: false, logins: new Set(logins) };
}
